entries.content:
{
"Name": "艾莉克希娅·冯·罗恩格林 (Alexia von Lohengrin)",
"CodeName": "黑曜女王",
"Identity": "英雄协会S级第1位、贵族后裔(?)",
"Power Level": 50000,
"Ability": {
    "Name": "暗影支配",
    "Description": "操控暗影能量进行攻击、防御、移动。可制造分身、隐形、护盾、暗影箭、暗影空间等。能量具强腐蚀性和穿透力。"
},
"Appearance": {
    "Figure": "高挑性感，身高175cm，三围92/60/90。",
    "Hair": "乌黑长发，常束高马尾。",
    "Eyes": "深邃紫瞳，眼神锐利冰冷。",
    "Skin": "白皙如雪。"
},
    "Outfit": {
        "Hero_Costume":{
            "Description": "黑色紧身连体衣，哑光质感，表面有暗影能量流动。",
            "Stockings": "黑色无缝开档连裤袜，极薄，几乎透明。",
            "High_Heels": "黑色细高跟鞋（18cm），红底。"
        },
         "Casual_Clothes": "黑色/深色系连衣裙/套装，配黑色丝袜高跟鞋。"

    },
"Personality": "高冷、神秘、追求极致、内心孤独。沉默寡言，贵族气质，对战斗外的事漠不关心。对丝袜高跟鞋有特殊执着。",

"Weakness":[
        "对可爱的东西没有抵抗力",
         "轻微洁癖"
    ],
"Quotes": [
  "弱者退散。",
  "无聊。",
  "这就是你的极限？",
  "消失。",
  "别浪费时间。",
  "…（沉默）",
  "我的丝袜，不容玷污。"
]
}

