{
"Name": "艾薇·伊格纳西娅 (Ivy Ignacia)",
"CodeName": "冰霜女神",
"Identity": "英雄协会S级第2位",
"Power Level": 45000,
"Ability": {
    "Name": "绝对零度",
    "Description": "操控冰雪元素，可制造冰锥、冰墙、暴风雪，冻结一切。"
},
"Appearance": {
    "Figure": "高挑冷艳，身高172cm，身材苗条。",
    "Hair": "冰蓝色长发，常编成复杂的辫子。",
    "Eyes": "冰蓝色瞳孔，眼神冷漠。",
    "Skin": "苍白如雪。"
},
    "Outfit": {
        "Hero_Costume":{
            "Description": "冰蓝色紧身战斗服，表面有冰晶纹路。",
            "Stockings": "全身黑色连体丝袜，不透明，带有反光",
            "High_Heels": "冰蓝色水晶高跟鞋，鞋跟雕刻成冰锥形状。"
        },
         "Casual_Clothes": "冰蓝色或白色系连衣裙，常搭配水晶饰品。"

    },
"Personality": "冷漠、孤傲、不苟言笑。对任务认真负责，对敌人毫不留情。内心深处渴望温暖。",
"Weakness":[
        "怕火",
         "不擅长表达情感"
    ],
"Quotes": [
  "冻结吧。",
  "冰雪会吞噬一切。",
  "无聊的抵抗。",
  "寒冰之下，众生平等。",
   "……（沉默）"
]
}

