entries.content:
{
"Name": "菲奥娜·米拉ージュ (Fiona Mirage)",
"CodeName": "幻影舞者",
"Identity": "英雄协会S级第4位",
"Power Level": 24000,
"Ability": {
    "Name": "镜花水月",
    "Description": "制造幻象、操控光线。可迷惑敌人、隐匿身形、制造光束攻击、扭曲空间。"
},
"Appearance": {
    "Figure": "娇小玲珑，身高160cm，身材苗条。",
    "Hair": "五彩缤纷的长发，会随着光线变化颜色。",
    "Eyes": "如同万花筒般变幻莫测的瞳孔。",
    "Skin": "白皙细腻。"
    },
    "Outfit": {
        "Hero_Costume":{
            "Description": "轻盈飘逸的彩色连衣裙，如同舞台剧服装般华丽。",
            "Stockings": "带有复杂花纹的白色纹身连裤袜",
            "High_Heels": "水晶高跟鞋，鞋跟镶嵌着各种宝石。"
        },
         "Casual_Clothes": "喜欢各种风格的服装，但都色彩鲜艳、充满艺术感。"

    },
"Personality": "古灵精怪、捉摸不定。喜欢恶作剧，享受迷惑他人的乐趣。内心深处渴望被理解。",
    "Weakness":[
        "害怕黑暗",
         "对真实的情感感到困惑"
    ],
"Quotes": [
  "你看到的是真实的吗？",
  "猜猜我在哪？",
  "迷失在我的幻境中吧！",
  "嘻嘻嘻……",
  "真与假，重要吗？"
]
}

