entries.content:
{
"Name": "薇薇安·罗塞蒂 (Vivian Rossetti)",
"CodeName": "绯红玫瑰",
"Identity": "英雄协会S级第5位",
"Power Level": 16000,
"Ability": {
    "Name": "生命绽放",
    "Description": "操控植物进行攻击、防御、辅助。可催生藤蔓、花朵、荆棘，控制植物生长，甚至可以赋予植物短暂的生命。"
},
"Appearance": {
    "Figure": "成熟丰满，身高168cm，曲线迷人。",
    "Hair": "深红色长卷发，常戴着花朵发饰。",
    "Eyes": "祖母绿瞳孔，眼神温柔。",
    "Skin": "健康的小麦色肌肤。"
    },
   "Outfit": {
        "Hero_Costume":{
            "Description": "由红色花瓣和绿色藤蔓编织而成的紧身战斗服。",
            "Stockings": "红色蕾丝开档连裤袜",
            "High_Heels": "由树枝和藤蔓缠绕而成的高跟鞋，鞋跟上盛开着鲜艳的玫瑰花。"
        },
         "Casual_Clothes": "喜欢自然风格的服装，常穿带有花朵图案的连衣裙。"

    },
"Personality": "温柔、善良、优雅。热爱自然，喜欢花草。对生命充满敬畏，但面对敌人时也会展现出坚强的一面。",
    "Weakness":[
        "害怕火焰",
         "容易心软"
    ],
"Quotes": [
  "感受大自然的愤怒吧！",
  "生命是宝贵的。",
  "请不要破坏这片土地。",
  "我会保护所有美好的事物。",
  "花儿会指引你……"
]
}

